(function ($) {
    "use strict";

    var editMode = false;

// modal popup script starts

var exclusiveModalPopup = function ($scope, $) {

    var modalWrapper        = $scope.find( '.exad-modal' ).eq(0),
        modalOverlayWrapper = $scope.find( '.exad-modal-overlay' ),
        modalItem           = $scope.find( '.exad-modal-item' ),
        modalAction         = modalWrapper.find( '.exad-modal-image-action' ),
        closeButton         = modalWrapper.find( '.exad-close-btn' );

    // Timer buka/tutup disimpan per modal dan dibatalkan setiap aksi baru:
    // buka lalu tutup cepat (<50ms) tidak lagi membuat modal muncul kembali setelah ditutup.
    var clearModalTimers = function( $item ) {
        $item.each( function() {
            var $el = $( this );
            clearTimeout( $el.data( 'exadOpenTimer' ) );
            clearTimeout( $el.data( 'exadCloseTimer' ) );
        } );
    };

    // PU-06 (keputusan 2026-10-19): musik latar (widget Audio) dijeda selama video Popup diputar, lalu dilanjutkan
    // saat Popup ditutup bila tadinya sedang berbunyi.
    var pauseMusicFor = function( $item ) {
        var adaVideo = $item.find( 'video' ).length || $item.find( 'iframe' ).filter( function() {
            return /youtube\.com|youtu\.be/.test( $( this ).attr( 'src' ) || $( this ).attr( 'data-src' ) || '' );
        } ).length;
        var bridges = window.wdpAudioBridges || {};
        var ids = [];
        if ( adaVideo ) {
            $( '.wdp-audio-wrapper.is-playing' ).each( function() {
                var id = $( this ).data( 'player-id' );
                if ( id && bridges[ id ] ) {
                    bridges[ id ].pauseVideo();
                    ids.push( id );
                }
            } );
        }
        $item.data( 'exadMusicIds', ids );
    };
    var resumeMusic = function() {
        var bridges = window.wdpAudioBridges || {};
        modalItem.each( function() {
            var ids = $( this ).data( 'exadMusicIds' ) || [];
            $( this ).data( 'exadMusicIds', [] );
            ids.forEach( function( id ) {
                if ( bridges[ id ] ) {
                    bridges[ id ].playVideo();
                }
            } );
        } );
    };

    var closeModal = function() {
        clearModalTimers( modalItem );
        resumeMusic();
        modalOverlayWrapper.removeClass( 'active' );
        modalItem.removeClass( 'active' );
        // PU-03: sembunyikan setelah animasi tutup selesai (Rotation 0,8 dtk; dulu dipotong di 300 ms).
        var tutupMs = 300;
        modalItem.each( function() {
            var dur = parseFloat( window.getComputedStyle( this ).transitionDuration ) || 0;
            tutupMs = Math.max( tutupMs, dur * 1000 );
        } );
        modalItem.data( 'exadCloseTimer', setTimeout( function() {
            if ( ! modalItem.hasClass( 'active' ) ) {
                modalItem.css( 'display', 'none' );
            }
        }, tutupMs ) );

        // Stop video playback on close; avoid reloading regular external_page iframes
        var isExternalPage = modalItem.hasClass( 'external_page' );
        if ( ! isExternalPage ) {
            var modal_iframe = modalWrapper.find( 'iframe' );
            if ( modal_iframe.length ) {
                var currentSrc = modal_iframe.attr( 'src' );
                if ( currentSrc && currentSrc.indexOf( 'youtube' ) !== -1 ) {
                    if ( modal_iframe.attr( 'data-src' ) ) {
                        // PD-80: video dilepas; dimuat lagi saat popup dibuka berikutnya.
                        modal_iframe.attr( 'src', 'about:blank' );
                    } else {
                        var modal_src = currentSrc.replace( '&autoplay=1', '' );
                        modal_iframe.attr( 'src', '' );
                        modal_iframe.attr( 'src', modal_src );
                    }
                }
            }
        }

        var $modal_video_tag = modalWrapper.find( 'video' );
        if ( $modal_video_tag.length && $modal_video_tag[0] ) {
            $modal_video_tag[0].pause();
            $modal_video_tag[0].currentTime = 0;
        }
    };

    modalAction.off( 'click.exadModal' ).on( 'click.exadModal', function(e) {
        e.preventDefault();
        var currentWrapper = $(this).closest( '.exad-modal' );
        var modalOverlay   = currentWrapper.find( '.exad-modal-overlay' );
        var targetModalId  = $(this).data( 'exad-modal' );
        // Utamakan modal di dalam widget ini; ID global hanya cadangan (widget yang sama bisa tampil dua kali).
        var targetModal    = currentWrapper.find( '.exad-modal-item' ).first();
        if ( ! targetModal.length && targetModalId ) {
            targetModal = $( targetModalId ).first();
        }
        var overlay        = $(this).data( 'exad-overlay' );
        if ( ! targetModal.length ) {
            return;
        }

        var modalIframe = targetModal.find( 'iframe.exad-modal-iframe' );
        if ( modalIframe.length ) {
            var dataSrc = modalIframe.attr( 'data-src' );
            var currentSrc = modalIframe.attr( 'src' );
            if ( dataSrc && ( ! currentSrc || 'about:blank' === currentSrc ) ) {
                modalIframe.attr( 'src', dataSrc );
            }
        }

        clearModalTimers( targetModal );
        pauseMusicFor( targetModal );
        targetModal.css( 'display', 'block' );
        targetModal.data( 'exadOpenTimer', setTimeout( function() {
            targetModal.addClass( 'active' );
        }, 50 ) );

        if ( 'yes' === overlay ) {
            modalOverlay.addClass( 'active' );
        }
    } );

    closeButton.off( 'click.exadModal' ).on( 'click.exadModal', function(e) {
        e.preventDefault();
        closeModal();
    } );

    modalOverlayWrapper.off( 'click.exadModal' ).on( 'click.exadModal', function() {
        var overlay_click_close = $(this).data( 'exad_overlay_click_close' );
        if ( 'yes' === overlay_click_close ) {
            closeModal();
        }
    } );

    // PD-80: tombol Esc menutup popup yang sedang terbuka.
    var escNs = 'keydown.exadModal' + ( $scope.data( 'id' ) || '' );
    $( document ).off( escNs ).on( escNs, function( e ) {
        if ( ( 'Escape' === e.key || 'Esc' === e.key ) && modalItem.hasClass( 'active' ) ) {
            closeModal();
        }
    } );
};

// modal popup script ends



$(window).on('elementor/frontend/init', function () {
    if( elementorFrontend.isEditMode() ) {
        editMode = true;
    }
    
    
    elementorFrontend.hooks.addAction( 'frontend/element_ready/weddingpress-modal-popup.default', exclusiveModalPopup );

});	

}(jQuery));